/**
 * The Slabyrinth logo — the one source of truth for its geometry and colours.
 * A dark rounded tile with a gold labyrinth: three concentric square rings, each broken by one
 * gap (bottom, left, bottom), around a centre stone. It is the mark on the website
 * (site/assets/img/icon-256.png, favicon-32.png), the window/taskbar/installer icon
 * (build/, generated by scripts/make-icons.ts) and the in-app <Mark> (renderer/ui/Icon.tsx).
 *
 * Coordinates are normalised to the tile: x and y run from -1 (left/top) to 1 (right/bottom).
 */

export type MarkGapSide = "bottom" | "left";

export interface MarkRing {
  /** Half-size of the ring's centre line (the ring is the square max(|x|, |y|) = half). */
  half: number;
  /** Edge that carries the ring's single gap, centred on that edge. */
  gap: MarkGapSide;
}

export const MARK = {
  /** Corner radius of the rounded-square tile. */
  tileRadius: 0.22,
  rings: [
    { half: 0.72, gap: "bottom" },
    { half: 0.5, gap: "left" },
    { half: 0.28, gap: "bottom" },
  ] satisfies readonly MarkRing[],
  /** Half the ring stroke width. */
  ringHalfWidth: 0.055,
  /** Half the length of each ring gap. */
  gapHalfLength: 0.12,
  /** Half-size of the solid centre stone. */
  centreHalf: 0.1,
  /** Brand colours (the same in dark and light theme, as on the website). */
  colors: { tile: "#14161a", ink: "#d9b56c" },
} as const;
